// Byte-identity check for the admin reply envelope against vectors/admin-reply.json, generated by
// `spindle-helper`'s `gen-admin-reply-vectors` (td-efea19/td-2c9d43). A mismatch means the Rust
// encoder and this package's decoder have drifted; neither side is authoritative without this.

import { describe, expect, it } from "vitest";

import { bytesToHex, CborValue } from "@spindle/proto";

import { encodeAdminReply, type AdminReply } from "../src/reply.js";
import { loadVectorFile } from "./helpers.js";

interface ReplyCase {
  name: string;
  description: string;
  canonical_cbor_hex: string;
}

interface ReplyDoc {
  artifact: string;
  cases: ReplyCase[];
}

const doc = loadVectorFile("admin-reply.json") as ReplyDoc;

if (doc.cases.length !== 4) {
  throw new Error(`expected 4 admin-reply vector cases, found ${doc.cases.length}`);
}

function replyFor(name: string): AdminReply {
  switch (name) {
    case "ok_no_result":
      return { v: 1, ok: true };
    case "ok_with_result":
      return { v: 1, ok: true, result: CborValue.text("ready") };
    case "refused_code_only":
      return { v: 1, ok: false, error: { code: "replay" } };
    case "refused_code_and_message":
      return {
        v: 1,
        ok: false,
        error: { code: "invalid_args", message: "host_fp must be 32 bytes" },
      };
    default:
      throw new Error(`unknown reply vector case ${name}`);
  }
}

describe("admin reply envelope: golden vectors", () => {
  for (const c of doc.cases) {
    it(`${c.name}: encodeAdminReply is byte-identical to vectors/admin-reply.json`, () => {
      expect(bytesToHex(encodeAdminReply(replyFor(c.name)))).toBe(c.canonical_cbor_hex);
    });
  }
});
